+const navToggle = document.querySelector(".nav-toggle");
+const navMenu = document.querySelector("#nav-menu");
+const filterButtons = document.querySelectorAll(".filter-button");
+const products = document.querySelectorAll(".product-card");
+const statusMessage = document.querySelector("#status-message");
+const addButtons = document.querySelectorAll("[data-product]");
+const newsletterForm = document.querySelector("#newsletter-form");
+const formMessage = document.querySelector("#form-message");
+
+navToggle.addEventListener("click", () => {
+  const isOpen = navToggle.getAttribute("aria-expanded") === "true";
+  navToggle.setAttribute("aria-expanded", String(!isOpen));
+  navMenu.classList.toggle("is-open", !isOpen);
+});
+
+filterButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    const selectedCategory = button.dataset.filter;
+    let visibleCount = 0;
+
+    filterButtons.forEach((item) => {
+      const isSelected = item === button;
+      item.classList.toggle("is-active", isSelected);
+      item.setAttribute("aria-pressed", String(isSelected));
+    });
+
+    products.forEach((product) => {
+      const shouldShow =
+        selectedCategory === "all" || product.dataset.category === selectedCategory;
+      product.hidden = !shouldShow;
+
+      if (shouldShow) {
+        visibleCount += 1;
+      }
+    });
+
+    const label = selectedCategory === "all" ? "all categories" : selectedCategory;
+    statusMessage.textContent = `Showing ${visibleCount} products in ${label}.`;
+  });
+});
+
+addButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    statusMessage.textContent = `${button.dataset.product} added to your bag.`;
+  });
+});
+
+newsletterForm.addEventListener("submit", (event) => {
+  event.preventDefault();
+  const email = new FormData(newsletterForm).get("email");
+  formMessage.textContent = `Thanks. Design notes will be sent to ${email}.`;
+  newsletterForm.reset();
+});
+

')

